<?php namespace Workspace; ?>
<p><a href="<?= h(url('oss',['project'=>$pid])) ?>">← OSS-проект</a> · <a href="<?= h(url('security')) ?>">MFA</a></p>
<section class="panel inset"><h2>Релизные линии</h2><p>Названия и ветки предназначены для публичного changelog. Отключение линии сохраняет историю, но запрещает новые назначения и выпуски.</p>
<form method="post" class="formgrid"><?php formFields('oss.line') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="version" value="0"><label>Публичное название<input name="label" maxlength="100" required></label><label>Ветка (например, release/1.x)<input name="branch" maxlength="100" required></label><button class="primary">Добавить линию</button></form>
<?php foreach($lines as $l): ?><div class="splitrow"><div><a href="<?= h(url('oss_maintenance',['project'=>$pid,'line'=>$l['id']])) ?>"><?= h($l['label']) ?></a><small><?= h($l['branch']) ?> · <?= (int)$l['active']?'Поддерживается':'Закрыта' ?></small></div><form method="post"><?php formFields('oss.line') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="line_id" value="<?= (int)$l['id'] ?>"><input type="hidden" name="version" value="<?= (int)$l['version'] ?>"><input type="hidden" name="active" value="<?= 1-(int)$l['active'] ?>"><button class="secondary compact"><?= (int)$l['active']?'Закрыть':'Возобновить' ?></button></form></div><?php endforeach ?></section>
<?php if(!$line)return; ?>
<section class="panel inset"><h2>Triage — <?= h($line['label']) ?></h2><form method="get" class="inline"><input type="hidden" name="p" value="oss_maintenance"><input type="hidden" name="project" value="<?= $pid ?>"><input type="hidden" name="line" value="<?= (int)$line['id'] ?>"><label>Состояние<select name="state"><?php selectOptions([''=>'Все','unassigned'=>'Не назначены']+OSS_LINE_STATES,$state) ?></select></label><button class="secondary">Фильтровать</button></form>
<?php foreach($queue as $q): ?><div class="splitrow"><div><a href="<?= h(url('oss_maintenance',['project'=>$pid,'line'=>$line['id'],'id'=>$q['id'],'state'=>$state,'n'=>$page])) ?>">#<?= (int)$q['id'] ?> <?= h($q['title']) ?></a><small><?= h(OSS_STATES[$q['contribution_state']]) ?> · <?= h(OSS_LINE_STATES[$q['state']??'']??'Не назначен') ?><?= $q['pr_number']?' · PR #'.(int)$q['pr_number']:'' ?></small></div></div><?php endforeach ?>
<?php if(!$queue): ?><p>Нет вкладов.</p><?php endif ?>
<?php if($selected): ?><article class="panel inset"><h3><?= h($selected['title']) ?></h3><p><a href="<?= h(url('oss',['project'=>$pid,'id'=>$selected['id']])) ?>">Исходный вклад и общее решение triage</a></p><p><?= h(OSS_LINE_STATES[$fix['state']??'']??'Не назначен') ?></p>
<?php if((int)$line['active']&&($fix['state']??'')!=='released'): ?><form method="post" class="formgrid"><?php formFields('oss.fix') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="line_id" value="<?= (int)$line['id'] ?>"><input type="hidden" name="contribution_id" value="<?= (int)$selected['id'] ?>"><input type="hidden" name="version" value="<?= (int)($fix['version']??0) ?>"><label>Решение<select name="state"><?php selectOptions(array_diff_key(OSS_LINE_STATES,['released'=>true]),$fix['state']??'planned') ?></select></label><label>PR исправления / backport (номер в upstream)<input type="number" min="1" max="999999999999" name="pr_number" value="<?= h($fix['pr_number']??'') ?>"></label><label>Внутренняя причина<textarea name="reason" maxlength="4000"><?= h($fix['reason']??'') ?></textarea></label><button class="primary">Сохранить triage и уведомить автора при смене состояния</button></form><?php else: ?><p>Запись закрыта для изменения.</p><?php endif ?></article><?php endif ?>
<nav><?php if($page>1): ?><a href="<?= h(url('oss_maintenance',['project'=>$pid,'line'=>$line['id'],'state'=>$state,'n'=>$page-1])) ?>">← Назад</a><?php endif ?> <?php if($more): ?><a href="<?= h(url('oss_maintenance',['project'=>$pid,'line'=>$line['id'],'state'=>$state,'n'=>$page+1])) ?>">Далее →</a><?php endif ?></nav></section>
<section class="panel inset"><h2>Публикация changelog линии</h2><p>Сначала опубликуйте релиз в GitHub. Workspace проверит публичность upstream, точный тег и принадлежность SHA ветке, merge каждого выбранного PR и его включение в тег. Публикуются только явно введённые тексты и ранее согласованные публичные заметки. До <?= OSS_FIX_LIMIT ?> исправлений за выпуск.</p>
<?php if((int)$line['active']&&(int)$cfg['published']&&$ready): ?><form method="post" class="stack"><?php formFields('oss.line.publish') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="line_id" value="<?= (int)$line['id'] ?>"><input type="hidden" name="version" value="<?= (int)$line['version'] ?>"><label>Тег<input name="tag" maxlength="100" required></label><label>Точный SHA тега<input name="commit_sha" pattern="[a-f0-9]{40}" maxlength="40" required></label><label>Публичное название<input name="title" maxlength="180" required></label><label>Публичный changelog<textarea name="notes" maxlength="4000" required></textarea></label><fieldset><legend>Готовые исправления (первые 50)</legend><?php foreach($ready as $r): ?><label><input type="checkbox" name="fixes[]" value="<?= (int)$r['contribution_id'] ?>:<?= (int)$r['version'] ?>"> PR #<?= (int)$r['pr_number'] ?> · <?= h($r['public_note']) ?></label><?php endforeach ?></fieldset><button class="primary">Проверить GitHub и опубликовать changelog</button></form><?php else: ?><p>Нет готовых исправлений или линия/публичный профиль закрыты.</p><?php endif ?>
<?php foreach($releases as $r): ?><div class="splitrow"><div><b><?= h($r['tag']) ?> · <?= h($r['title']) ?></b><small><?= h($r['commit_sha']) ?> · <?= h(gmdate('Y-m-d H:i',(int)$r['published_at'])) ?> UTC</small></div><a href="<?= h('https://github.com/'.$cfg['upstream'].'/releases/tag/'.rawurlencode($r['tag'])) ?>" rel="noopener noreferrer">GitHub</a></div><?php endforeach ?></section>
